INSERT INTO mfg_auth.wf_definition(def_code,def_name,biz_type,def_version,is_enabled,description) SELECT 'CRM_QUOTATION_APPROVAL','销售报价审批','QUOTATION',1,1,'按折扣与毛利审批' WHERE NOT EXISTS(SELECT 1 FROM mfg_auth.wf_definition WHERE def_code='CRM_QUOTATION_APPROVAL' AND def_version=1);
INSERT INTO mfg_auth.wf_node(definition_id,node_seq,node_name,approver_role,approve_mode,is_required,reject_action) SELECT id,10,'销售主管审批','SALES_SUPERVISOR','SINGLE',1,'BACK' FROM mfg_auth.wf_definition d WHERE d.def_code='CRM_QUOTATION_APPROVAL' AND NOT EXISTS(SELECT 1 FROM mfg_auth.wf_node n WHERE n.definition_id=d.id AND n.node_seq=10);
INSERT INTO mfg_auth.wf_definition(def_code,def_name,biz_type,def_version,is_enabled,description) SELECT 'CRM_CONTRACT_APPROVAL','销售合同审批','CONTRACT',1,1,'销售与财务联合审批' WHERE NOT EXISTS(SELECT 1 FROM mfg_auth.wf_definition WHERE def_code='CRM_CONTRACT_APPROVAL' AND def_version=1);
INSERT INTO mfg_auth.wf_node(definition_id,node_seq,node_name,approver_role,approve_mode,is_required,reject_action) SELECT id,10,'销售总监审批','SALES_DIRECTOR','SINGLE',1,'BACK' FROM mfg_auth.wf_definition d WHERE d.def_code='CRM_CONTRACT_APPROVAL' AND NOT EXISTS(SELECT 1 FROM mfg_auth.wf_node n WHERE n.definition_id=d.id AND n.node_seq=10);
INSERT INTO mfg_auth.wf_node(definition_id,node_seq,node_name,approver_role,approve_mode,is_required,reject_action) SELECT id,20,'财务主管审批','FINANCE_SUPERVISOR','SINGLE',1,'BACK' FROM mfg_auth.wf_definition d WHERE d.def_code='CRM_CONTRACT_APPROVAL' AND NOT EXISTS(SELECT 1 FROM mfg_auth.wf_node n WHERE n.definition_id=d.id AND n.node_seq=20);
INSERT INTO mfg_auth.sys_permission(perm_code,perm_name,system_code,perm_type) SELECT x.code,x.name,x.system_code,'BUTTON' FROM (SELECT 'CRM:LEAD:CREATE' code,'新建线索' name,'crm' system_code UNION ALL SELECT 'CRM:LEAD:ASSIGN','分配线索','crm' UNION ALL SELECT 'CRM:OPPORTUNITY:STAGE','推进商机','crm' UNION ALL SELECT 'CRM:QUOTATION:SUBMIT','提交报价','crm' UNION ALL SELECT 'CRM:CONTRACT:ACTIVATE','生效合同','crm' UNION ALL SELECT 'ERP:SALES_ORDER:CONFIRM','确认销售订单','erp' UNION ALL SELECT 'ERP:CREDIT:APPROVE','信用例外审批','erp' UNION ALL SELECT 'ERP:ATP:COMMIT','确认交期','erp' UNION ALL SELECT 'ERP:MRP:RUN','运行物料需求计划','erp' UNION ALL SELECT 'ERP:PRODUCTION_ORDER:RELEASE','下达生产订单','erp' UNION ALL SELECT 'ERP:FINANCE:RECEIPT','登记回款','erp' UNION ALL SELECT 'ERP:FINANCE:SETTLE','回款核销','erp' UNION ALL SELECT 'ERP:FINANCE:COST_VIEW','查看成本毛利','erp')x WHERE NOT EXISTS(SELECT 1 FROM mfg_auth.sys_permission p WHERE p.perm_code=x.code);
